export default [
  {"id": "FOR-H-0jjj8i", "grade": "6", "unit": "FOR", "level": 1, "lo": "FOR-26", "q": "A book is sitting completely still on a level table. According to Newton's First Law, which of the following statements best explains why the book remains at rest?", "a": ["A constant force is being applied to the book, pushing it down into the table.", "The table is exerting a force that is slightly greater than gravity, holding the book up.", "The forces acting on the book are balanced, meaning the net force is zero.", "The book has no forces acting on it at all."], "correct": 2, "why": "The book remains at rest because the upward normal force from the table and the downward weight are balanced. Their vector sum is zero, so the net force is zero.", "image": null, "imageAlt": null, "src": "FOR-26_Balanced_forces_explain_rest"},
  {"id": "FOR-H-1yom2e", "grade": "6", "unit": "FOR", "level": 1, "lo": "FOR-48", "q": "Which combination of SI base units is equivalent to one newton?", "a": ["$1\\ \\frac{\\mathrm{kg}\\cdot\\mathrm{m}^2}{\\mathrm{s}^2}$", "$1\\ \\frac{\\mathrm{kg}\\cdot\\mathrm{m}}{\\mathrm{s}}$", "$1\\ \\frac{\\mathrm{kg}}{\\mathrm{m}\\cdot\\mathrm{s}^2}$", "$1\\ \\frac{\\mathrm{kg}\\cdot\\mathrm{m}}{\\mathrm{s}^2}$"], "correct": 3, "why": "One newton is the force that gives a 1 kg mass an acceleration of 1 m/s². In SI base units, 1 N = 1 kg·m/s².", "image": null, "imageAlt": null, "src": "FOR-48_newton_in_base_units"},
  {"id": "FOR-H-77cqxo", "grade": "6", "unit": "FOR", "level": 1, "lo": "FOR-02", "q": "What is the SI unit for weight?", "a": ["Meter per second ($\\frac{\\mathrm{m}}{\\mathrm{s}}$)", "Kilogram (kg)", "Joule (J)", "Newton (N)"], "correct": 3, "why": "Weight is a force, so its SI unit is the newton (N). The kilogram is a mass unit, m/s is a speed unit, and the joule is an energy unit.", "image": null, "imageAlt": null, "src": "FOR-02_si_unit_of_weight_newton"},
  {"id": "FOR-H-nx5n5i", "grade": "6", "unit": "FOR", "level": 1, "lo": "FOR-26", "q": "Two people push on opposite sides of a gate with equal force. Which statement is correct?", "a": ["The forces are balanced, so the net force on the gate is zero.", "The forces are unbalanced, so the net force on the gate is zero.", "The forces are balanced, so the net force on the gate equals one of the forces.", "The forces are unbalanced, so the net force on the gate equals the sum of the forces."], "correct": 0, "why": "The two pushes have equal size and opposite directions, so they cancel. The net force on the gate is zero.", "image": null, "imageAlt": null, "src": "FOR-26_balanced_forces_gate"},
  {"id": "FOR-H-0x6nzs", "grade": "7", "unit": "FOR", "level": 1, "lo": "FOR-35", "q": "All the forces acting on a moving object are balanced. What happens to the object?", "a": ["It immediately stops.", "It continues moving at constant velocity.", "It speeds up in the direction of motion.", "It changes direction."], "correct": 1, "why": "Balanced forces produce zero net force and therefore zero acceleration. The object keeps moving at constant velocity.", "image": null, "imageAlt": null, "src": "FOR-35_balanced_forces_moving_object"},
  {"id": "FOR-H-3vmdj9", "grade": "7", "unit": "FOR", "level": 1, "lo": "FOR-13", "q": "Object A has a mass of $3\\,\\mathrm{kg}$ and object B has a mass of $12\\,\\mathrm{kg}$. Which statement correctly compares their inertia?", "a": ["Object B has four times the inertia of object A.", "Object B has nine times the inertia of object A.", "Object A has four times the inertia of object B.", "The two objects have the same inertia."], "correct": 0, "why": "Inertia increases with mass. Object B has 12 kg compared with 3 kg for object A, so B has 12/3 = 4 times the inertia.", "image": null, "imageAlt": null, "src": "FOR-13_compare_inertia"},
  {"id": "FOR-H-d06n05", "grade": "7", "unit": "FOR", "level": 1, "lo": "FOR-42", "q": "A rocket expels gas downward. The gas pushes upward on the rocket. Why does the rocket move upward?", "a": ["The gas force acts after the rocket's force.", "The forces act on different objects, so the upward force on the rocket is not canceled by the downward force on the gas.", "The forces cancel, but the rocket still moves.", "The gas force is larger than the rocket's force on the gas."], "correct": 1, "why": "The rocket pushes gas downward, and the gas pushes the rocket upward. These are an action-reaction pair acting on different objects, so the upward force on the rocket is not canceled by the downward force on the gas.", "image": null, "imageAlt": null, "src": "FOR-D06_mcq_rocket_gas"},
  {"id": "FOR-H-myaq8f", "grade": "7", "unit": "FOR", "level": 1, "lo": "FOR-21", "q": "A box slides to the right across a rough floor. In which direction does the kinetic friction force act on the box?", "a": ["up", "down", "to the right", "to the left"], "correct": 3, "why": "Kinetic friction acts opposite the sliding motion. The box slides right, so kinetic friction acts to the left.", "image": null, "imageAlt": null, "src": "FOR-21_kinetic_friction_direction"},
  {"id": "FOR-H-njo4pd", "grade": "7", "unit": "FOR", "level": 1, "lo": "FOR-16", "q": "Newton's first law is also known as the law of ______.", "a": ["gravity", "acceleration", "force", "inertia"], "correct": 3, "why": "Newton’s first law describes inertia, so it is also called the law of inertia.", "image": null, "imageAlt": null, "src": "FOR-16_law_of_inertia_name"},
  {"id": "FOR-H-p6v0kd", "grade": "7", "unit": "FOR", "level": 1, "lo": "FOR-42", "q": "Two hockey players push off each other on the ice. The forces on the players are equal in size and opposite in direction. Why don't the forces cancel?", "a": ["The forces act on different players, so each player feels only one force from the pair.", "The forces act at different times.", "The forces are not really equal in size.", "The forces act in the same direction."], "correct": 0, "why": "Action and reaction forces act on different objects. The force on one player and the force on the other player do not cancel because they are not acting on the same object.", "image": null, "imageAlt": null, "src": "FOR-42_hockey_players_not_cancel_g7"},
  {"id": "FOR-H-28b0eb", "grade": "7", "unit": "FOR", "level": 2, "lo": "FOR-30", "q": "Three forces act on a box, all pointing to the right, as shown. Which force has the greatest magnitude?", "a": ["$F_2$", "$F_3$", "All three forces are equal.", "$F_1$"], "correct": 1, "why": "The length of a force arrow represents the magnitude of the force. The arrow for $F_3$ is the longest, so $F_3$ has the greatest magnitude.", "image": "questions/images/for/28b0eb.svg", "imageAlt": "A box with three rightward force arrows labeled F1, F2, and F3; the arrows get longer from F1 to F3.", "src": "FOR-30_force_arrow_magnitude"},
  {"id": "FOR-H-2yewf4", "grade": "7", "unit": "FOR", "level": 2, "lo": "FOR-30", "q": "Three tugboats pull a barge to the right. The arrows show the forces $F_1$, $F_2$, and $F_3$ they exert. Which tugboat exerts the greatest force?", "a": ["$F_3$", "$F_1$", "$F_2$", "All three forces are equal."], "correct": 0, "why": "The longest force arrow represents the largest force. The arrow for $F_3$ is longest, so the tugboat exerting $F_3$ pulls hardest.", "image": "questions/images/for/2yewf4.svg", "imageAlt": "A barge with three rightward force arrows labeled F1, F2, and F3; F3 is the longest arrow.", "src": "FOR-30_force_arrow_magnitude_02"},
  {"id": "FOR-H-8bmvhy", "grade": "7", "unit": "FOR", "level": 2, "lo": "FOR-47", "q": "A crate is pulled right by a rope across a rough floor. Which list gives the forces on the crate and their causes?", "a": ["tension (rope), friction (floor), normal (floor), weight (gravity)", "tension (floor), friction (rope), normal (gravity), weight (floor)", "friction (rope), weight (floor), tension (gravity), normal (crate)", "applied (rope), tension (floor), weight (friction), normal (gravity)"], "correct": 0, "why": "The rope exerts tension, the floor exerts friction and a normal force, and Earth exerts the weight due to gravity.", "image": null, "imageAlt": null, "src": "FOR-47_identify_forces"},
  {"id": "FOR-H-d4awsn", "grade": "7", "unit": "FOR", "level": 2, "lo": "FOR-36", "q": "Which statement correctly classifies each situation?", "a": ["Both are in dynamic equilibrium.", "A parked car is in static equilibrium, and a train moving at constant speed is in dynamic equilibrium.", "A parked car is in dynamic equilibrium, and a train moving at constant speed is in static equilibrium.", "Both are in static equilibrium."], "correct": 1, "why": "A parked car is at rest, which is static equilibrium. A train moving at constant speed has zero acceleration, which is dynamic equilibrium.", "image": null, "imageAlt": null, "src": "FOR-36_static_dynamic_pair"},
  {"id": "FOR-H-qpkqjw", "grade": "7", "unit": "FOR", "level": 2, "lo": "FOR-35", "q": "A skydiver falls at a constant velocity before opening the parachute. Which statement correctly describes the forces and acceleration?", "a": ["The forces are unbalanced, so the skydiver moves at constant velocity.", "The forces are balanced, the net force is zero, and the acceleration is zero.", "The net force is downward, so the acceleration is zero.", "The forces are balanced, but the skydiver still accelerates."], "correct": 1, "why": "Constant velocity means zero acceleration. The upward air resistance balances the downward weight, so the net force is zero.", "image": null, "imageAlt": null, "src": "FOR-35_skydiver_constant_velocity"},
  {"id": "FOR-H-ry2fsp", "grade": "7", "unit": "FOR", "level": 2, "lo": "FOR-36", "q": "Box A is at rest on a table. Box B slides across a floor at constant velocity. Which statement correctly classifies the boxes?", "a": ["Both boxes are in dynamic equilibrium.", "Both boxes are in static equilibrium.", "Box A is in static equilibrium, and Box B is in dynamic equilibrium.", "Box A is in dynamic equilibrium, and Box B is in static equilibrium."], "correct": 2, "why": "An object at rest is in static equilibrium. An object moving at constant velocity is in dynamic equilibrium because its acceleration and net force are zero.", "image": null, "imageAlt": null, "src": "FOR-36_static_dynamic_boxes"},
  {"id": "FOR-H-05uoek", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-10", "q": "Which of the following best defines an object's inertia?", "a": ["The force of gravity acting on an object.", "The speed at which an object is moving.", "The amount of matter contained in an object.", "The tendency of an object to resist changes in its motion."], "correct": 3, "why": "Inertia is an object’s tendency to resist changes in its motion. It depends on mass, not on gravity or speed.", "image": null, "imageAlt": null, "src": "FOR-10_define_inertia_concept"},
  {"id": "FOR-H-0tava9", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-03", "q": "A ball is dropped from rest near the Earth's surface, as shown. Ignoring air resistance, the gravitational acceleration of the ball while it falls is", "a": ["$9.8\\,\\frac{\\mathrm{m}}{\\mathrm{s}}$", "$98\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}$", "$9.8\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}$", "$9.8\\,\\mathrm{N}$"], "correct": 2, "why": "A freely falling object near Earth accelerates downward at about 9.8 m/s². Acceleration is measured in m/s², not in newtons or m/s.", "image": "questions/images/for/0tava9.svg", "imageAlt": "A ball of mass m falling near Earth, with a downward weight arrow labeled Fg and the ground below.", "src": "FOR-03_gravity_on_earth"},
  {"id": "FOR-H-0u2od7", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-15", "q": "An object is moving at a constant velocity. According to Newton's first law, what must be true about the forces acting on the object?", "a": ["The net force on the object is increasing.", "The forces are unbalanced.", "The net force on the object is zero.", "There are no forces at all acting on the object."], "correct": 2, "why": "Newton’s first law says motion does not change unless a net force acts. Constant velocity therefore means the net force is zero.", "image": null, "imageAlt": null, "src": "FOR-15_newtons_first_law_statement"},
  {"id": "FOR-H-2hdzdr", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-10", "q": "An object in motion tends to stay in motion because it has:", "a": ["force", "gravity", "inertia", "friction"], "correct": 2, "why": "An object in motion tends to keep moving because of inertia. No extra force is needed to maintain its motion at constant velocity.", "image": null, "imageAlt": null, "src": "FOR-10_Object_in_motion_inertia"},
  {"id": "FOR-H-3mse8v", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-25", "q": "A dog pushes his food bowl to the right with 24 N of force. Friction resists the motion with 10 N in the opposite direction. What is the net force on the bowl?", "a": ["34 N left", "14 N left", "14 N right", "34 N right"], "correct": 2, "why": "Take right as positive: $F_{net} = 24 - 10 = 14$ N right. The opposite forces subtract.", "image": null, "imageAlt": null, "src": "FOR-25_Dog_bowl_net_force"},
  {"id": "FOR-H-5ujwnp", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-10", "q": "A book is at rest on a table. According to the concept of inertia, what will happen to the book if the net force acting on it is zero?", "a": ["It will remain at rest.", "It will accelerate forward.", "It will move at a constant speed.", "It will slow down and stop."], "correct": 0, "why": "With zero net force, the book’s motion does not change. Since it is already at rest, it remains at rest.", "image": null, "imageAlt": null, "src": "FOR-10_inertia_at_rest_application"},
  {"id": "FOR-H-8de3io", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-03", "q": "A \\(5\\,\\mathrm{kg}\\) rock and a \\(1\\,\\mathrm{kg}\\) rock are dropped from the same height near Earth's surface. Air resistance is negligible. How do their gravitational accelerations compare?", "a": ["The \\(1\\,\\mathrm{kg}\\) rock has five times the acceleration.", "Both have an acceleration of \\(0\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}\\) because they are falling.", "The \\(5\\,\\mathrm{kg}\\) rock has five times the acceleration.", "Both have an acceleration of \\(9.8\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}\\)."], "correct": 3, "why": "Near Earth, all objects in free fall have the same acceleration of about 9.8 m/s² when air resistance is negligible. The acceleration does not depend on mass.", "image": null, "imageAlt": null, "src": "FOR-03_free_fall_acceleration_comparison"},
  {"id": "FOR-H-8u6wet", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-05", "q": "A \\(25\\,\\mathrm{kg}\\) crate is on Earth, where \\(g=9.8\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}\\). What is the magnitude of the crate's weight?", "a": ["\\(245\\,\\mathrm{N}\\)", "\\(2.6\\,\\mathrm{N}\\)", "\\(25\\,\\mathrm{N}\\)", "\\(9.8\\,\\mathrm{N}\\)"], "correct": 0, "why": "Weight is $F_{g} = mg$ = 25 kg × 9.8 m/s² = 245 N.", "image": null, "imageAlt": null, "src": "FOR-05_weight_earth_25kg"},
  {"id": "FOR-H-90fjhk", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-25", "q": "A 2.0 kg book is lifted at constant velocity. An upward force of 20 N is applied. What is the net force on the book?", "a": ["0 N", "20 N up", "4 N down", "20 N down"], "correct": 0, "why": "Constant velocity means zero acceleration. By $F_{net} = ma$, the net force must therefore be zero.", "image": null, "imageAlt": null, "src": "FOR-25_Book_lifted_constant_velocity"},
  {"id": "FOR-H-93vqmw", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-04", "q": "An object is taken from Earth to the Moon. Which statement correctly compares its mass and weight on the Moon with their values on Earth?", "a": ["Its mass decreases, but its weight stays the same.", "Both its mass and its weight decrease.", "Both its mass and its weight stay the same.", "Its mass stays the same, but its weight decreases."], "correct": 3, "why": "Mass is the amount of matter and does not change with location. Weight equals mg, and the Moon’s gravitational acceleration is smaller than Earth’s, so the object’s weight decreases.", "image": null, "imageAlt": null, "src": "FOR-04_mass_weight_moon_location"},
  {"id": "FOR-H-ad32ov", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-40", "q": "A basketball player stands on the floor. The floor pushes up on the player. Which force is the reaction to this push?", "a": ["The player's weight cancels the floor's push.", "Earth pulls down on the player.", "The floor pushes harder because the player is heavier.", "The player pushes down on the floor."], "correct": 3, "why": "The floor pushes up on the player; the reaction is the player pushing down on the floor with an equal force. Weight and normal force are separate forces acting on the player.", "image": null, "imageAlt": null, "src": "FOR-40_basketball_floor_reaction"},
  {"id": "FOR-H-ajlrif", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-20", "q": "The same box is easier to slide on smooth tile than on rough carpet. Which statement best explains why?", "a": ["The carpet pushes up harder, so friction is larger.", "Friction depends on speed, and the box moves faster on the tile.", "The tile is smoother, so the surfaces have a smaller coefficient of friction.", "The box is lighter on the tile, so there is less friction."], "correct": 2, "why": "A smoother surface has a smaller coefficient of friction, so less friction force is needed to slide the same box. The box’s weight does not change.", "image": null, "imageAlt": null, "src": "FOR-20_friction_surface_coefficient"},
  {"id": "FOR-H-apieb2", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-33", "q": "A snowflake falls with zero acceleration. Which statement about the snowflake is true?", "a": ["The air resistance on it is zero.", "It is moving with constant velocity.", "It is slowing down.", "It has a nonzero net force."], "correct": 1, "why": "Zero acceleration means the snowflake’s velocity is not changing. It is falling at constant velocity.", "image": null, "imageAlt": null, "src": "FOR-33_snowflake_zero_acceleration"},
  {"id": "FOR-H-c0euqs", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-33", "q": "A car travels along a straight, level road at a constant velocity. Which statement is true?", "a": ["The forces on the car are unbalanced.", "The car is accelerating because it is moving.", "The net force on the car is zero.", "A constant forward force is needed to keep the car moving."], "correct": 2, "why": "Constant velocity means zero acceleration. By $F_{net} = ma$, the net force on the car must be zero.", "image": null, "imageAlt": null, "src": "FOR-33_car_constant_velocity"},
  {"id": "FOR-H-d06n01", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-39", "q": "A swimmer pushes water backward and moves forward. Which statement best explains this?", "a": ["For every action force, there is an equal and opposite reaction force.", "An object at rest stays at rest unless a net force acts on it.", "The net force on an object equals its mass times its acceleration.", "Forces always cause motion in the direction of the applied force."], "correct": 0, "why": "The swimmer pushes water backward, and the water pushes the swimmer forward. This is an action-reaction pair described by Newton’s third law.", "image": null, "imageAlt": null, "src": "FOR-D06_mcq_swimmer_n3l"},
  {"id": "FOR-H-d06n02", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-40", "q": "A person walks forward. The person's foot pushes backward on the ground. Which force is the reaction force?", "a": ["The ground pushes up on the person.", "The person's weight pushes down on the ground.", "Earth pulls down on the person.", "The ground pushes forward on the person."], "correct": 3, "why": "The foot pushes the ground backward. The ground pushes forward on the person, which is the reaction force that moves the person forward.", "image": null, "imageAlt": null, "src": "FOR-D06_mcq_walking_reaction"},
  {"id": "FOR-H-d06n03", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-41", "q": "A truck collides with a mosquito. Which statement compares the forces they exert on each other?", "a": ["The truck and mosquito exert equal forces on each other.", "The mosquito exerts a larger force because it is smaller.", "The forces depend on their speeds, so they cannot be compared.", "The truck exerts a larger force because it has more mass."], "correct": 0, "why": "Newton’s third law says the forces are equal in size and opposite in direction, regardless of the masses or the resulting accelerations.", "image": null, "imageAlt": null, "src": "FOR-D06_mcq_truck_mosquito"},
  {"id": "FOR-H-d06n04", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-40", "q": "A book rests on a table. The table pushes up on the book. Which force is the reaction force?", "a": ["The table pushes up harder because the book is at rest.", "Earth pulls down on the book.", "The book pushes down on the table.", "The book's weight cancels the table's push."], "correct": 2, "why": "The table pushes up on the book. The reaction is the book pushing down on the table with an equal force.", "image": null, "imageAlt": null, "src": "FOR-D06_mcq_book_table_pair"},
  {"id": "FOR-H-d06n06", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-41", "q": "A hammer hits a nail. The hammer exerts a force on the nail. Which statement describes the force the nail exerts on the hammer?", "a": ["It acts in the same direction as the hammer's force.", "It is larger because the hammer is moving.", "It is smaller because the nail has less mass.", "It is equal in size and opposite in direction."], "correct": 3, "why": "The nail pushes back on the hammer with the same size force in the opposite direction. The hammer’s larger mass does not make its force larger.", "image": null, "imageAlt": null, "src": "FOR-D06_mcq_hammer_nail"},
  {"id": "FOR-H-ddraen", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-39", "q": "Which statement is Newton's third law of motion?", "a": ["An object at rest stays at rest unless a net force acts on it.", "Forces always cause motion in the direction of the force.", "The net force on an object equals its mass times its acceleration.", "For every action force, there is an equal and opposite reaction force."], "correct": 3, "why": "Newton’s third law says that for every action force there is an equal and opposite reaction force. The two forces act on different objects.", "image": null, "imageAlt": null, "src": "FOR-39_newtons_third_law_statement"},
  {"id": "FOR-H-e65esv", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-05", "q": "A student has a mass of $60\\,\\mathrm{kg}$. On Earth, where $g = 9.8\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}$, the student's weight is", "a": ["$600\\,\\mathrm{N}$", "$60\\,\\mathrm{N}$", "$9.8\\,\\mathrm{N}$", "$588\\,\\mathrm{N}$"], "correct": 3, "why": "The student’s weight is $F_{g} = mg$ = 60 kg × 9.8 m/s² = 588 N.", "image": null, "imageAlt": null, "src": "FOR-05_weight_of_a_student"},
  {"id": "FOR-H-g8bqqf", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-40", "q": "Which statement correctly describes an action-reaction pair?", "a": ["The forces are equal in size, opposite in direction, and act on different objects at the same time.", "The reaction force happens after the action force.", "The larger object exerts a larger force.", "The forces act on the same object and cancel."], "correct": 0, "why": "Action-reaction forces are equal in size, opposite in direction, act on different objects, and occur at the same time.", "image": null, "imageAlt": null, "src": "FOR-41_action_reaction_properties_g6"},
  {"id": "FOR-H-gqrzfo", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-20", "q": "Maria pushes a heavy box across a rough concrete floor at a constant speed. Which force directly opposes her push?", "a": ["tension, from the muscles in Maria's arms", "friction, caused by the box and floor surfaces rubbing", "the normal force, the floor pushing up on the box", "gravity, pulling the box down toward Earth"], "correct": 1, "why": "Friction is caused by the box and floor surfaces rubbing together, and it acts opposite the motion. The normal force and gravity act vertically, not against the push.", "image": null, "imageAlt": null, "src": "FOR-20_friction_opposes_motion"},
  {"id": "FOR-H-hs23zg", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-04", "q": "Which statement correctly describes the difference between mass and weight?", "a": ["Mass changes with location; weight stays the same.", "Mass is measured in newtons; weight is measured in kilograms.", "Mass is a force; weight is a measure of matter.", "Mass is the amount of matter in an object; weight is the gravitational force acting on it."], "correct": 3, "why": "Mass measures the amount of matter in an object. Weight is the gravitational force on the object and depends on the local value of g.", "image": null, "imageAlt": null, "src": "FOR-04_mass_vs_weight"},
  {"id": "FOR-H-hx3siq", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-37", "q": "Newton's second law states that the acceleration of an object is", "a": ["equal to the net force multiplied by the mass.", "independent of both the net force and the mass.", "inversely proportional to the net force and directly proportional to the mass.", "directly proportional to the net force and inversely proportional to the mass."], "correct": 3, "why": "Newton’s second law is $a = F_{net}/m$. Acceleration is directly proportional to net force and inversely proportional to mass.", "image": null, "imageAlt": null, "src": "FOR-37_cart_accelerates"},
  {"id": "FOR-H-iixunv", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-19", "q": "Which of the following is a non-contact force?", "a": ["the friction between a tire and the road", "the gravitational pull of Earth on the Moon", "the normal force of a table supporting a book", "the tension in a rope during a tug-of-war"], "correct": 1, "why": "Gravity acts between Earth and the Moon without the two touching, so it is a non-contact force. Friction, tension, and normal force require contact.", "image": null, "imageAlt": null, "src": "FOR-19_non_contact_force"},
  {"id": "FOR-H-k9f8nl", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-34", "q": "A cart is held at rest and then released. It begins to move to the right. What can you conclude about the forces on the cart after it is released?", "a": ["The forces are balanced, so the cart stays at rest.", "The net force on the cart is zero.", "The cart is in equilibrium.", "The forces are unbalanced, so the cart accelerates."], "correct": 3, "why": "Starting from rest and moving to the right means the cart is accelerating. The forces must therefore be unbalanced, producing a net force.", "image": null, "imageAlt": null, "src": "FOR-34_cart_released"},
  {"id": "FOR-H-l0etro", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-10", "q": "According to Newton's First Law, objects at rest tend to stay at rest because they have:", "a": ["gravity", "force", "inertia", "acceleration"], "correct": 2, "why": "An object at rest tends to stay at rest because of inertia. A net force is needed to change its state of motion.", "image": null, "imageAlt": null, "src": "FOR-10_Objects_at_rest_inertia"},
  {"id": "FOR-H-medrhv", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-08", "q": "Which of the following is a scalar quantity?", "a": ["acceleration", "force", "mass", "velocity"], "correct": 2, "why": "Mass has magnitude but no direction, so it is a scalar. Velocity, acceleration, and force all have direction and are vectors.", "image": null, "imageAlt": null, "src": "FOR-08_Mass_scalar_quantity_identify"},
  {"id": "FOR-H-o2po8w", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-18", "q": "Which of the following best defines a force in physics?", "a": ["A push or a pull that can cause an object to change its motion.", "The energy an object has because it is moving.", "The amount of matter contained in an object.", "The speed and direction an object is moving."], "correct": 0, "why": "A force is a push or a pull that can cause an object to change its motion. Matter, speed, and energy are different quantities.", "image": null, "imageAlt": null, "src": "FOR-18_best_definition_of_force"},
  {"id": "FOR-H-o6to5o", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-19", "q": "A book is stationary on a tilted ramp. Which pair of forces are both contact forces acting on the book?", "a": ["the electrostatic force and the normal force", "the tension in a string and the gravitational pull from Earth", "the force of gravity and a magnetic force", "the force of friction and the normal force from the ramp"], "correct": 3, "why": "Friction and the normal force both require the book and ramp to touch, so they are contact forces. Gravity and magnetic forces can act at a distance.", "image": null, "imageAlt": null, "src": "FOR-19_contact_force_pair"},
  {"id": "FOR-H-o83hgq", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-32", "q": "An object is in equilibrium. What must be true?", "a": ["The object's speed must be zero.", "No forces act on the object.", "The object must be at rest.", "The net force on the object is zero."], "correct": 3, "why": "Equilibrium means the net force is zero. The object may be at rest or moving at constant velocity; it does not have to be stationary.", "image": null, "imageAlt": null, "src": "FOR-32_equilibrium_condition"},
  {"id": "FOR-H-pjpkdx", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-01", "q": "What physical quantity is defined by the equation $F_g = mg$?", "a": ["Mass", "Density", "Acceleration", "Weight"], "correct": 3, "why": "The equation $F_{g} = mg$ gives the weight of an object: its mass m multiplied by the gravitational acceleration g. It does not define mass, acceleration, or density.", "image": null, "imageAlt": null, "src": "FOR-01_weight_equation_Fg_mg"},
  {"id": "FOR-H-si2ob2", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-34", "q": "A bicycle is slowing down as it approaches a stop sign. Is the bicycle in equilibrium?", "a": ["Yes, because the forces on it are balanced.", "Yes, because it remains on the ground.", "No, because its velocity is changing.", "No, because it is moving."], "correct": 2, "why": "Slowing down means the bicycle’s velocity is changing, so it is accelerating. Therefore the forces are unbalanced and it is not in equilibrium.", "image": null, "imageAlt": null, "src": "FOR-34_bicycle_slowing"},
  {"id": "FOR-H-tbjfdu", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-10", "q": "Which quantity is used to measure inertia?", "a": ["force, N", "time, s", "mass, kg", "length, m"], "correct": 2, "why": "Inertia is measured by mass. The SI unit of mass is the kilogram (kg).", "image": null, "imageAlt": null, "src": "FOR-10_Measure_inertia_quantity"},
  {"id": "FOR-H-tg5yq8", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-25", "q": "A person pushes a box to the left with 15 N of force. Friction resists the motion with 8 N in the opposite direction. What is the net force on the box?", "a": ["7 N right", "7 N left", "23 N right", "23 N left"], "correct": 1, "why": "Take left as positive: $F_{net} = 15 - 8 = 7$ N left. The forces are opposite, so their magnitudes subtract.", "image": null, "imageAlt": null, "src": "FOR-25_Box_pushed_left_net_force"},
  {"id": "FOR-H-tj3kf6", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-24", "q": "What is the definition of net force?", "a": ["the average of all forces acting on an object", "the (vector) sum of all forces acting on an object", "the sum of all magnitudes of forces acting on an object", "the difference between two forces acting on an object"], "correct": 1, "why": "Net force is the vector sum of all forces acting on an object. Directions matter, so the forces are added as vectors rather than as magnitudes only.", "image": null, "imageAlt": null, "src": "FOR-24_Define_net_force_vector"},
  {"id": "FOR-H-tvdahz", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-32", "q": "Which statement best defines equilibrium?", "a": ["All the forces acting on the object are equal in size.", "The object must be at rest.", "The net force on the object is zero and its acceleration is zero.", "The object is moving at constant speed in a circle."], "correct": 2, "why": "An object in equilibrium has zero net force and therefore zero acceleration. It can be at rest or moving at constant velocity.", "image": null, "imageAlt": null, "src": "FOR-32_equilibrium_definition"},
  {"id": "FOR-H-ut6p13", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-18", "q": "What is the definition of force?", "a": ["The direction of an object.", "The speed of an object.", "The mass of an object.", "A push or pull on an object."], "correct": 3, "why": "A force is a push or a pull on an object. Forces can change an object’s motion.", "image": null, "imageAlt": null, "src": "FOR-18_Define_force_push_pull"},
  {"id": "FOR-H-vxxfq4", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-20", "q": "The box is now sliding to the right across the floor. You are still pushing it to the right. Which way does kinetic friction act on the box, and why?", "a": ["To the left, because kinetic friction opposes the sliding between the box and the floor.", "It depends on the speed: faster sliding means friction points right.", "Downward, because friction is caused by gravity.", "To the right, because it acts in the same direction as your push."], "correct": 0, "why": "Kinetic friction opposes the sliding between surfaces. Since the box slides right, kinetic friction acts to the left.", "image": null, "imageAlt": null, "src": "FOR-20_friction_opposes_sliding_g6"},
  {"id": "FOR-H-xdmuz0", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-19", "q": "A box is sitting still on a table. You push it gently to the right, but it does not move. Which statement best explains what friction is doing?", "a": ["Friction pulls down, adding to the box's weight.", "Friction pushes right, helping the box move.", "Static friction pushes left and matches your push, so the forces balance.", "There is no friction because the box is not moving."], "correct": 2, "why": "A gentle push to the right is balanced by static friction acting to the left. Because the net force is zero, the box does not move.", "image": null, "imageAlt": null, "src": "FOR-19_static_friction_at_rest"},
  {"id": "FOR-H-y0tn7z", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-08", "q": "Which statement best defines mass?", "a": ["The amount of space an object occupies.", "The force of gravity acting on an object.", "The amount of matter in an object.", "The tendency of an object to resist a change in motion."], "correct": 2, "why": "Mass is the amount of matter in an object. Weight is the gravitational force on the object, and inertia is the resistance to changes in motion.", "image": null, "imageAlt": null, "src": "FOR-08_mass_definition"},
  {"id": "FOR-H-yljr8f", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-40", "q": "A soccer player kicks the ball forward. Which force is the reaction to the player's foot pushing on the ball?", "a": ["The ball's reaction force happens after the kick.", "The player's foot pushes the ball harder because the player is heavier.", "The ball pushes back on the player's foot with the same size force.", "The ball pushes forward on the grass."], "correct": 2, "why": "The foot pushes the ball forward, so the ball pushes back on the foot with an equal force in the opposite direction.", "image": null, "imageAlt": null, "src": "FOR-40_soccer_kick_reaction"},
  {"id": "FOR-H-ywzkuy", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-41", "q": "A tennis racket hits a ball. The racket exerts a force on the ball. Which statement describes the force the ball exerts on the racket?", "a": ["It is equal in size and opposite in direction.", "It is smaller because the ball has less mass.", "It is larger because the racket is moving faster.", "It is in the same direction as the racket's force."], "correct": 0, "why": "By Newton’s third law, the ball pushes back on the racket with the same size force and in the opposite direction.", "image": null, "imageAlt": null, "src": "FOR-41_tennis_racket_ball_forces"},
  {"id": "FOR-H-zklne6", "grade": "both", "unit": "FOR", "level": 1, "lo": "FOR-18", "q": "A force is best described as which of the following?", "a": ["A push or a pull that can change an object's motion.", "The amount of matter in an object.", "The energy an object has because of its motion.", "The speed at which an object moves."], "correct": 0, "why": "A force is a push or a pull that can change an object’s motion. Mass, speed, and energy are not forces.", "image": null, "imageAlt": null, "src": "FOR-18_define_force_in_physics"},
  {"id": "FOR-H-0xjidv", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-28", "q": "A flowerpot rests on a windowsill. The free-body diagram shows two forces, $F_1$ and $F_2$, acting on the flowerpot. What are the two forces, and what is their effect?", "a": ["$F_1$ is the normal force upward and $F_2$ is weight downward; they are unbalanced.", "$F_1$ is tension upward and $F_2$ is friction downward; they are unbalanced.", "$F_1$ is weight upward and $F_2$ is the normal force downward; they balance.", "$F_1$ is the normal force upward and $F_2$ is weight downward; they balance."], "correct": 3, "why": "$F_1$ points upward and is the normal force from the windowsill. $F_2$ points downward and is the flowerpot’s weight. They balance because the flowerpot is at rest.", "image": "questions/images/for/0xjidv.svg", "imageAlt": "Free-body diagram of a flowerpot with F1 upward and F2 downward.", "src": "FOR-28_fbd_flowerpot"},
  {"id": "FOR-H-46e9ym", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-25", "q": "Two people are playing tug-of-war with a rope. Person A pulls to the left with a force of 300 N. Person B pulls to the right with a force of 250 N. What is the net force on the rope, and what will happen to its motion?", "a": ["The net force is 50 N to the left, and the rope will accelerate to the left.", "The net force is 550 N, and the rope will move to the right at a constant speed.", "The net force is 50 N to the right, and the rope will move with a constant velocity to the right.", "The net force is 0 N, and the rope will remain at rest."], "correct": 0, "why": "Take left as positive: $F_{net} = 300 - 250 = 50$ N left. The rope accelerates in the direction of the net force.", "image": null, "imageAlt": null, "src": "FOR-25_Net_force_tug_war"},
  {"id": "FOR-H-6r7icp", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-38", "q": "A skydiver jumps from a plane. As her speed increases, air resistance increases. Which statement is correct?", "a": ["Her acceleration decreases, and at terminal velocity the net force on her is zero.", "Her acceleration stays at $9.8\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}$ until she opens her parachute.", "At terminal velocity, her weight is zero.", "Air resistance decreases as her speed increases."], "correct": 0, "why": "As speed increases, air resistance increases and the upward force on the skydiver grows. At terminal velocity, air resistance balances weight, so the net force and acceleration are zero.", "image": null, "imageAlt": null, "src": "FOR-38_terminal_velocity"},
  {"id": "FOR-H-8a2gc0", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-06", "q": "An astronaut has a mass of $90\\,\\mathrm{kg}$. On the Moon, where $g = 1.6\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}$, the astronaut's weight is", "a": ["$882\\,\\mathrm{N}$", "$90\\,\\mathrm{N}$", "$144\\,\\mathrm{N}$", "$56\\,\\mathrm{N}$"], "correct": 2, "why": "Weight on the Moon is $F_{g} = mg$ = 90 kg × 1.6 m/s² = 144 N.", "image": null, "imageAlt": null, "src": "FOR-06_astronaut_on_moon"},
  {"id": "FOR-H-8b6y8t", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-25", "q": "The box slides right at a constant speed while you push it to the right with 20 N. What must the friction force be?", "a": ["20 N to the right, because friction acts with your push.", "0 N, because the box is moving at constant speed.", "20 N to the left, because constant velocity means the net force is zero.", "More than 20 N, because friction is always stronger than the push."], "correct": 2, "why": "Constant velocity means zero net force. The 20 N push to the right must be balanced by 20 N of friction to the left.", "image": null, "imageAlt": null, "src": "FOR-25_friction_at_constant_speed"},
  {"id": "FOR-H-8qqahj", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-38", "q": "A \\(4.0\\,\\mathrm{kg}\\) cart has a net force of \\(12\\,\\mathrm{N}\\) to the right. What is the cart's acceleration?", "a": ["\\(3.0\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}\\) to the right.", "\\(0.33\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}\\) to the left.", "\\(48\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}\\) to the right.", "\\(3.0\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}\\) to the left."], "correct": 0, "why": "Use $a = F_{net}/m$ = 12 N / 4.0 kg = 3.0 m/s². The acceleration is in the same direction as the net force, to the right.", "image": null, "imageAlt": null, "src": "FOR-38_net_force_acceleration_cart"},
  {"id": "FOR-H-922700", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-28", "q": "A box rests on a table. The free-body diagram shows all the forces acting on the box. What are the two forces, and what is their effect?", "a": ["Applied force and weight; they balance.", "Friction and normal force; they balance.", "Tension up and friction down.", "Normal force up and weight down; they balance."], "correct": 3, "why": "The free-body diagram shows normal force upward and weight downward. They are equal and opposite, so they balance.", "image": "questions/images/for/922700.svg", "imageAlt": "Free-body diagram of a box with normal force FN upward and weight Fg downward.", "src": "FOR-28_box_on_table_fbd"},
  {"id": "FOR-H-abwvvo", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-19", "q": "You push harder and harder until the box just begins to slide. At the moment the box starts moving, what happens to the friction force?", "a": ["It becomes zero because the box is moving.", "It increases because the box is now moving.", "It changes to kinetic friction, which is smaller than the maximum static friction.", "It stays at the maximum static friction."], "correct": 2, "why": "Once the box starts sliding, static friction is replaced by kinetic friction. Kinetic friction is smaller than the maximum static friction.", "image": null, "imageAlt": null, "src": "FOR-19_static_to_kinetic"},
  {"id": "FOR-H-cdgcq0", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-28", "q": "A sled is pulled to the right along a horizontal snow surface by a rope. Friction acts on the sled. The free-body diagram shows the forces acting on the sled. Which statement about the forces on the sled is correct?", "a": ["The vertical forces are unbalanced. There is a net force to the right.", "The vertical forces are balanced. The horizontal forces are balanced too, so the net force is zero.", "The vertical forces are balanced. There is a net force to the right.", "The horizontal forces are balanced. There is a net force upward."], "correct": 2, "why": "The normal force and weight are vertical and balance. The tension to the right is larger than friction to the left, so there is a net force to the right.", "image": "questions/images/for/cdgcq0.svg", "imageAlt": "Free-body diagram of a sled with normal force upward, weight downward, tension to the right, and friction to the left.", "src": "FOR-28_fbd_two_dimensions_sled"},
  {"id": "FOR-H-eilzn2", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-06", "q": "A \\(60\\,\\mathrm{kg}\\) astronaut is on the Moon, where \\(g=1.6\\,\\frac{\\mathrm{m}}{\\mathrm{s^2}}\\). What is the astronaut's weight on the Moon?", "a": ["\\(37.5\\,\\mathrm{N}\\)", "\\(96\\,\\mathrm{N}\\)", "\\(61.6\\,\\mathrm{N}\\)", "\\(600\\,\\mathrm{N}\\)"], "correct": 1, "why": "Weight on the Moon is $F_{g} = mg$ = 60 kg × 1.6 m/s² = 96 N.", "image": null, "imageAlt": null, "src": "FOR-06_weight_moon_60kg"},
  {"id": "FOR-H-ijqzn9", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-19", "q": "A heavy crate is at rest. A small push does not move it, but a stronger push makes it slide. Which statement compares the friction forces?", "a": ["The kinetic friction is greater than the maximum static friction.", "The maximum static friction is greater than the kinetic friction.", "Static friction acts only after the crate starts moving.", "Static friction and kinetic friction are always equal."], "correct": 1, "why": "It takes a larger force to overcome maximum static friction than to keep the crate sliding. Therefore maximum static friction is greater than kinetic friction.", "image": null, "imageAlt": null, "src": "FOR-19_static_vs_kinetic"},
  {"id": "FOR-H-j1ut4x", "grade": "both", "unit": "FOR", "level": 2, "lo": "FOR-11", "q": "A coin rests on a card covering the mouth of a cup. The card is flicked sideways, and the coin drops into the cup. Why does the coin drop into the cup instead of moving sideways with the card?", "a": ["The coin has inertia, so it resists the sudden change in motion.", "Gravity pulls the coin sideways with the card.", "The card pushes the coin down into the cup.", "The coin has no forces acting on it."], "correct": 0, "why": "The coin has inertia, so it tends to remain at rest when the card is flicked away. Gravity then pulls the coin down into the cup.", "image": "questions/images/for/j1ut4x.svg", "imageAlt": "A coin resting on a card over the mouth of a cup.", "src": "FOR-11_coin_card_inertia"},
];
